privacyProvidersP1:
  "Plainspeak Now™ relies on third-party service providers to operate certain features. These providers may process information as necessary to perform services on our behalf, such as account authentication and data storage, document and image text extraction, artificial intelligence processing, audio generation, payment processing, email delivery, hosting, and related infrastructure. Their handling of information is also subject to their own terms and privacy practices.",

