termsLegalTitle: "Detailed Terms of Service",

termsServiceTitle: "1. The Service",

termsServiceP1:
  "Plainspeak Now™ provides tools designed to help users understand and work with written documents. Depending on the features selected, the service may rewrite content in clearer language, organize information, identify critical, urgent, or important items, create a professional response draft, translate content, extract text from documents or images, or generate audio.",

termsAdviceTitle: "2. Not Professional Advice",

termsAdviceP1:
  "Plainspeak Now™ is an informational and communication tool and does not provide legal, medical, financial, tax, or other professional advice. Use of the service does not create an attorney-client, doctor-patient, financial-advisor, or other professional relationship. You should consult an appropriately qualified professional when professional advice is needed.",

termsAccuracyTitle: "3. AI-Generated Results and Accuracy",

termsAccuracyP1:
  "Plainspeak Now™ uses automated and artificial intelligence technologies. Results may contain errors, omissions, inaccurate interpretations, or imperfect translations or audio. You are responsible for reviewing results and comparing important information with the original document before relying on or acting upon them. The original document remains the authoritative source for its contents.",

termsKeysTitle: "4. Keys and Usage",

termsKeysP1:
  "Plainspeak Now™ uses Keys to process documents. Documents up to 35 pages use 1 Key, and documents from 36 to 70 pages use 2 Keys. Keys are deducted when a document is successfully processed. Keys do not expire. Plainspeak Now™ may establish reasonable technical, security, or usage limits to protect the service and its users.",

termsPaymentsTitle: "5. Purchases and Refunds",

termsPaymentsP1:
  "Purchases of Keys are one-time purchases and do not create a subscription or automatic recurring charge. Payments are processed through a third-party payment provider. If a purchased service does not work as expected, contact us at hello@plainspeaknow.net. Refund requests are reviewed based on the circumstances and any rights provided by applicable law.",

termsContentTitle: "6. Your Content",

termsContentP1:
  "You retain any rights you have in content you submit to Plainspeak Now™. You give us permission to process that content only as reasonably necessary to provide, secure, troubleshoot, and operate the service. You are responsible for ensuring that you have the right to submit and process the content you provide. Our handling of personal information and document content is described in our Privacy Policy.",

termsAcceptableTitle: "7. Acceptable Use",

termsAcceptableP1:
  "You may not misuse Plainspeak Now™, attempt to gain unauthorized access to the service or another user's account, interfere with or disrupt the service, bypass security or usage controls, use automated methods to scrape or overload the service, submit content in violation of applicable law or the rights of others, or use the service to facilitate unlawful or harmful activity.",

termsAvailabilityTitle: "8. Service Availability",

termsAvailabilityP1:
  "We work to keep Plainspeak Now™ available and functioning properly, but we do not guarantee that the service will always be available, uninterrupted, error-free, or compatible with every document. Features may occasionally be changed, limited, suspended, or unavailable because of maintenance, security issues, technical problems, third-party service interruptions, or other operational needs.",

