  "Espacio reservado para una opinión", 
    faqTitle: "Preguntas Frecuentes",
faqSubtitle: "Respuestas sencillas sobre cómo funciona Plainspeak Now™.",

faqQ1:
  "¿Por qué no usar simplemente ChatGPT?",

faqA1:
  "Puedes hacerlo. Plainspeak Now™ está diseñado específicamente para facilitar la comprensión de documentos reales que pueden ser complicados o confusos, sin que tengas que averiguar qué preguntar ni cómo escribir un prompt.",

faqA1b:
  "Carga tu documento, pega el texto o toma una foto del documento. Plainspeak Now™ lo procesa mediante un proceso coherente centrado en la claridad, la información importante y los próximos pasos prácticos.",

faqQ2:
  "¿Qué hace Plainspeak Now™?",

faqA2:
  "Plainspeak Now™ reescribe documentos complejos en un lenguaje cotidiano más claro, conservando la información importante. Tu resultado también puede identificar elementos críticos, urgentes e importantes, proporcionar un borrador de respuesta profesional cuando corresponda y traducirse o reproducirse como audio.",

faqQ3:
  "¿Qué son las Keys?",

faqA3:
  "Las Keys se utilizan para procesar documentos con Plainspeak Now™.",

faqA3Bullet1:
  "Los documentos de hasta 35 páginas usan 1 Key",

faqA3Bullet2:
  "Los documentos de 36 a 70 páginas usan 2 Keys",

faqA3Bullet3:
  "Las Keys solo se descuentan cuando el documento se procesa correctamente",

faqA3b:
  "Las Keys nunca vencen y no se requiere una suscripción.",

faqQ4:
  "¿Recibo una Key gratis?",

faqA4:
  "Sí. Las cuentas nuevas reciben 1 Key gratis para que puedas probar Plainspeak Now™. También se te puede ofrecer una Key adicional por proporcionar tus comentarios.",

faqQ5:
  "¿Las Keys vencen?",

faqA5:
  "No. Tus Keys permanecen en tu cuenta hasta que las uses.",

faqQ6:
  "¿Qué sucede si me quedo sin Keys?",

faqA6:
  "Puedes comprar más Keys cuando las necesites. No hay suscripción ni cargos recurrentes automáticos.",

faqQ7:
  "¿Qué tipos de documentos puedo usar?",

faqA7:
  "Puedes pegar texto, cargar un archivo de documento compatible o tomar o cargar una foto de un documento. Plainspeak Now™ admite archivos PDF, DOCX, TXT, CSV y XLSX, además de fotos de documentos y capturas de pantalla. Los documentos pueden tener hasta 70 páginas.",

faqQ8:
  "¿Qué sucede con mi documento después de procesarlo?",

faqA8:
  "Tu documento se utiliza para crear tu resultado de Plainspeak y se elimina de nuestro servidor después del procesamiento. Consulta nuestra Política de Privacidad para obtener más información sobre cómo se manejan los datos durante el procesamiento.",

faqQ9: "¿Plainspeak Now™ admite otros idiomas?",

faqA9:
  "Sí. Plainspeak Now™ admite inglés, español, vietnamita, tagalo, francés, chino simplificado, coreano, árabe, portugués, ruso, criollo haitiano e hindi.",

faqQ10: "¿Puede Plainspeak Now™ leer mi resultado en voz alta?",

faqA10:
  "Sí. Puedes generar una reproducción de audio de tu resultado de Plainspeak. El audio está disponible en los idiomas compatibles.",

faqQ11:
  "¿Plainspeak Now™ ofrece asesoramiento legal, médico, financiero u otro tipo de asesoramiento profesional?",

faqA11:
  "No. Plainspeak Now™ te ayuda a comprender información complicada en un lenguaje más claro, pero no ofrece asesoramiento legal, médico, financiero ni ningún otro tipo de asesoramiento profesional. Para tomar decisiones que afecten tus derechos, salud, beneficios, finanzas u obligaciones, consulta a un profesional cualificado.",

faqQ12: "¿Plainspeak Now™ cambia el significado de mi documento?",

faqA12:
  "Plainspeak Now™ está diseñado para conservar el significado y los detalles importantes de tu documento mientras facilita la comprensión del lenguaje. La inteligencia artificial puede cometer errores, así que utiliza el documento original como fuente autorizada y revisa cuidadosamente las decisiones importantes.",

faqQ13: "¿Puedo obtener un reembolso?",

faqA13:
  "Si tienes algún problema con una compra o Plainspeak Now™ no funciona como esperabas, contáctanos. Las solicitudes de reembolso se gestionan de acuerdo con nuestros Términos de uso.",

faqLastUpdated: "Última actualización: agosto de 2026",

