whyTitle:
  "Por qué creé Plainspeak Now™",

whyParagraph1:
  "Durante años, mi propia familia ha acudido a mí cuando los documentos eran confusos, abrumadores o simplemente difíciles de entender. He visto lo estresante que puede ser un documento importante cuando no estás completamente seguro de lo que te pide que hagas.",

whyParagraph2:
  "Creé Plainspeak Now™ para hacer esos momentos un poco más fáciles. No deberías necesitar un título en derecho, un título en medicina ni un diccionario a tu lado solo para entender los documentos que afectan tu vida.",

