    faqTitle: "Câu Hỏi Thường Gặp",
faqSubtitle: "Những câu trả lời đơn giản về cách Plainspeak hoạt động.",

faqQ1:
  "Tại sao không chỉ sử dụng ChatGPT?",

faqA1:
  "Bạn hoàn toàn có thể. Plainspeak Now™ được thiết kế riêng để giúp các tài liệu thực tế phức tạp hoặc khó hiểu trở nên dễ hiểu hơn, mà bạn không cần phải tự nghĩ xem nên hỏi gì hoặc viết câu lệnh như thế nào.",

faqA1b:
  "Tải tài liệu lên, dán văn bản hoặc chụp ảnh tài liệu. Plainspeak Now™ xử lý tài liệu theo một quy trình nhất quán, tập trung vào sự rõ ràng, thông tin quan trọng và các bước tiếp theo thiết thực.",

faqQ2:
  "Plainspeak Now™ làm gì?",

faqA2:
  "Plainspeak Now™ viết lại các tài liệu phức tạp bằng ngôn ngữ đời thường, rõ ràng hơn trong khi vẫn giữ lại những thông tin quan trọng. Kết quả cũng có thể xác định các mục nghiêm trọng, khẩn cấp và quan trọng, cung cấp bản nháp phản hồi chuyên nghiệp khi phù hợp, đồng thời có thể được dịch hoặc phát dưới dạng âm thanh.",

faqQ3:
  "Keys là gì?",

faqA3:
  "Keys được sử dụng để xử lý tài liệu với Plainspeak Now™.",

faqA3Bullet1:
  "Tài liệu tối đa 35 trang sử dụng 1 Key",

faqA3Bullet2:
  "Tài liệu từ 36 đến 70 trang sử dụng 2 Keys",

faqA3Bullet3:
  "Keys chỉ được trừ khi tài liệu được xử lý thành công",

faqA3b:
  "Keys không bao giờ hết hạn và không yêu cầu đăng ký.",

faqQ4:
  "Tôi có được nhận Key miễn phí không?",

faqA4:
  "Có. Tài khoản mới nhận được 1 Key miễn phí để bạn có thể dùng thử Plainspeak Now™. Bạn cũng có thể được tặng thêm 1 Key khi cung cấp phản hồi.",

faqQ5:
  "Keys có hết hạn không?",

faqA5:
  "Không. Keys sẽ ở trong tài khoản của bạn cho đến khi bạn sử dụng chúng.",

faqQ6:
  "Điều gì xảy ra nếu tôi hết Keys?",

faqA6:
  "Bạn có thể mua thêm Keys khi cần. Không có đăng ký và không có khoản phí định kỳ tự động.",

faqQ7:
  "Tôi có thể sử dụng những loại tài liệu nào?",

faqA7:
  "Bạn có thể dán văn bản, tải lên tệp tài liệu được hỗ trợ hoặc chụp hay tải lên ảnh của tài liệu. Plainspeak Now™ hỗ trợ các tệp PDF, DOCX, TXT, CSV và XLSX, cũng như ảnh tài liệu và ảnh chụp màn hình. Tài liệu có thể dài tối đa 70 trang.",

faqQ8:
  "Điều gì xảy ra với tài liệu của tôi sau khi được xử lý?",

faqA8:
  "Tài liệu của bạn được sử dụng để tạo kết quả Plainspeak và được xóa khỏi máy chủ của chúng tôi sau khi xử lý. Hãy xem Chính sách quyền riêng tư của chúng tôi để biết thêm thông tin về cách dữ liệu được xử lý trong quá trình này.",

faqQ9: "Plainspeak Now™ có hỗ trợ các ngôn ngữ khác không?",

faqA9:
  "Có. Plainspeak Now™ hỗ trợ tiếng Anh, tiếng Tây Ban Nha, tiếng Việt, tiếng Tagalog, tiếng Pháp, tiếng Trung giản thể, tiếng Hàn, tiếng Ả Rập, tiếng Bồ Đào Nha, tiếng Nga, tiếng Creole Haiti và tiếng Hindi.",

faqQ10: "Plainspeak Now™ có thể đọc kết quả cho tôi nghe không?",

faqA10:
  "Có. Bạn có thể tạo bản phát âm thanh cho kết quả Plainspeak của mình. Âm thanh có sẵn bằng các ngôn ngữ được hỗ trợ.",

faqQ11:
  "Plainspeak Now™ có cung cấp tư vấn pháp lý, y tế, tài chính hoặc tư vấn chuyên môn khác không?",

faqA11:
  "Không. Plainspeak Now™ giúp bạn hiểu thông tin phức tạp bằng ngôn ngữ rõ ràng hơn, nhưng không cung cấp tư vấn pháp lý, y tế, tài chính hoặc tư vấn chuyên môn khác. Đối với các quyết định ảnh hưởng đến quyền lợi, sức khỏe, phúc lợi, tài chính hoặc nghĩa vụ của bạn, hãy tham khảo ý kiến của một chuyên gia có đủ trình độ.",

faqQ12: "Plainspeak Now™ có thay đổi ý nghĩa của tài liệu không?",

faqA12:
  "Plainspeak Now™ được thiết kế để giữ nguyên ý nghĩa và các chi tiết quan trọng của tài liệu đồng thời giúp ngôn ngữ dễ hiểu hơn. AI có thể mắc lỗi, vì vậy hãy sử dụng tài liệu gốc làm nguồn thông tin chính thức và xem xét cẩn thận trước khi đưa ra các quyết định quan trọng.",

faqQ13: "Tôi có thể được hoàn tiền không?",

faqA13:
  "Nếu bạn gặp vấn đề với giao dịch mua hoặc Plainspeak Now™ không hoạt động như mong đợi, hãy liên hệ với chúng tôi. Các yêu cầu hoàn tiền được xử lý theo Điều khoản sử dụng của chúng tôi.",

