    faqTitle: "Mga Madalas Itanong",
faqSubtitle: "Mga simpleng sagot tungkol sa kung paano gumagana ang Plainspeak.",

faqQ1:
  "Bakit hindi na lang gumamit ng ChatGPT?",

faqA1:
  "Maaari mo naman. Ang Plainspeak Now™ ay partikular na ginawa upang gawing mas madaling maunawaan ang mga komplikado o nakalilitong dokumento sa totoong buhay, nang hindi mo kailangang alamin kung ano ang itatanong o kung paano gumawa ng tamang prompt.",

faqA1b:
  "I-upload ang iyong dokumento, i-paste ang teksto, o kumuha ng larawan ng dokumento. Pinoproseso ito ng Plainspeak Now™ sa isang pare-parehong paraan na nakatuon sa malinaw na paliwanag, mahalagang impormasyon, at praktikal na mga susunod na hakbang.",

faqQ2:
  "Ano ang ginagawa ng Plainspeak Now™?",

faqA2:
  "Muling isinusulat ng Plainspeak Now™ ang mga komplikadong dokumento gamit ang mas malinaw at pang-araw-araw na wika habang pinapanatili ang mahalagang impormasyon. Maaari ring tukuyin ng iyong resulta ang mga kritikal, agarang, at mahalagang bagay, magbigay ng draft ng propesyonal na tugon kapag naaangkop, at maisalin o mapakinggan bilang audio.",

faqQ3:
  "Ano ang mga Keys?",

faqA3:
  "Ginagamit ang Keys upang iproseso ang mga dokumento sa Plainspeak Now™.",

faqA3Bullet1:
  "Ang mga dokumentong hanggang 35 pahina ay gumagamit ng 1 Key",

faqA3Bullet2:
  "Ang mga dokumentong 36 hanggang 70 pahina ay gumagamit ng 2 Keys",

faqA3Bullet3:
  "Ibinabawas lamang ang Keys kapag matagumpay na naproseso ang dokumento",

faqA3b:
  "Hindi nag-e-expire ang Keys, at walang kinakailangang subscription.",

faqQ4:
  "Makakakuha ba ako ng libreng Key?",

faqA4:
  "Oo. Ang mga bagong account ay makakatanggap ng 1 libreng Key upang masubukan mo ang Plainspeak Now™. Maaari ka ring alukin ng bonus na Key kapag nagbigay ka ng feedback.",

faqQ5:
  "Nag-e-expire ba ang Keys?",

faqA5:
  "Hindi. Mananatili ang iyong Keys sa iyong account hanggang sa gamitin mo ang mga ito.",

faqQ6:
  "Ano ang mangyayari kung maubusan ako ng Keys?",

faqA6:
  "Maaari kang bumili ng karagdagang Keys kapag kailangan mo ang mga ito. Walang subscription at walang awtomatikong paulit-ulit na singil.",

faqQ7:
  "Anong mga uri ng dokumento ang maaari kong gamitin?",

faqA7:
  "Maaari kang mag-paste ng teksto, mag-upload ng sinusuportahang file ng dokumento, o kumuha o mag-upload ng larawan ng isang dokumento. Sinusuportahan ng Plainspeak Now™ ang PDF, DOCX, TXT, CSV, at XLSX na mga file, pati na rin ang mga larawan ng dokumento at screenshot. Maaaring hanggang 70 pahina ang isang dokumento.",

faqQ8:
  "Ano ang mangyayari sa aking dokumento pagkatapos itong maproseso?",

faqA8:
  "Ginagamit ang iyong dokumento upang gawin ang iyong resulta sa Plainspeak at pagkatapos ay binubura ito mula sa aming server matapos itong maproseso. Tingnan ang aming Patakaran sa Privacy para sa higit pang impormasyon tungkol sa kung paano pinangangasiwaan ang data habang pinoproseso ito.",

faqQ9: "Sinusuportahan ba ng Plainspeak Now™ ang ibang mga wika?",

faqA9:
  "Oo. Sinusuportahan ng Plainspeak Now™ ang English, Spanish, Vietnamese, Tagalog, French, Simplified Chinese, Korean, Arabic, Portuguese, Russian, Haitian Creole, at Hindi.",

faqQ10: "Maaari bang basahin nang malakas ng Plainspeak Now™ ang aking resulta?",

faqA10:
  "Oo. Maaari kang gumawa ng audio playback ng iyong resulta sa Plainspeak. Available ang audio sa mga sinusuportahang wika.",

faqQ11:
  "Nagbibigay ba ang Plainspeak Now™ ng legal, medikal, pinansyal, o iba pang propesyonal na payo?",

faqA11:
  "Hindi. Tinutulungan ka ng Plainspeak Now™ na maunawaan ang komplikadong impormasyon gamit ang mas malinaw na wika, ngunit hindi ito nagbibigay ng legal, medikal, pinansyal, o iba pang propesyonal na payo. Para sa mga desisyong nakaaapekto sa iyong mga karapatan, kalusugan, benepisyo, pananalapi, o obligasyon, kumonsulta sa isang kwalipikadong propesyonal.",

faqQ12: "Binabago ba ng Plainspeak Now™ ang kahulugan ng aking dokumento?",

faqA12:
  "Idinisenyo ang Plainspeak Now™ upang mapanatili ang kahulugan at mahahalagang detalye ng iyong dokumento habang ginagawang mas madaling maunawaan ang wika. Maaaring magkamali ang AI, kaya gamitin ang orihinal na dokumento bilang opisyal na sanggunian at suriing mabuti ang mahahalagang desisyon.",

faqQ13: "Maaari ba akong makakuha ng refund?",

faqA13:
  "Kung magkaroon ka ng problema sa isang pagbili o hindi gumana ang Plainspeak Now™ gaya ng inaasahan, makipag-ugnayan sa amin. Ang mga kahilingan para sa refund ay pinangangasiwaan ayon sa aming Mga Tuntunin ng Paggamit.",
