includesTranslationTitle: "Traduction",
includesTranslationDescription:
  "Consultez votre résultat en langage clair dans une langue prise en charge.",
  
  whyAlt:
  "Ma famille, la raison pour laquelle j’ai créé Plainspeak Now",

whyEyebrow:
  "La raison derrière Plainspeak",

whyTitle:
  "Pourquoi j’ai créé Plainspeak Now™",

whyParagraph1:
  "Pendant des années, ma propre famille s’est tournée vers moi lorsque les documents étaient déroutants, accablants ou tout simplement difficiles à comprendre. J’ai vu à quel point un document important peut devenir stressant lorsqu’on ne sait pas exactement ce qu’il nous demande de faire.",

whyParagraph2:
  "J’ai créé Plainspeak Now™ pour rendre ces moments un peu plus faciles. Vous ne devriez pas avoir besoin d’un diplôme en droit, d’un diplôme en médecine ou d’un dictionnaire à vos côtés simplement pour comprendre les documents qui ont un impact sur votre vie.",

whyClosing:
  "Vous méritez de comprendre avant de vous engager.",

videoEyebrow: "Découvrez-le en action",

videoTitle: "Découvrez comment fonctionne Plainspeak Now™",

videoDescription:
  "Passez d’un document difficile à comprendre à des prochaines étapes claires en quelques minutes.",

videoWalkthroughTitle:
  "Guide de Plainspeak Now™",

videoWalkthroughDescription:
  "Une courte vidéo étape par étape vous montrera comment téléverser un document, obtenir votre résultat et utiliser les outils inclus.",

videoComingSoon:
  "Vidéo bientôt disponible",

  faq: "FAQ",

  faqTitle: "Questions fréquemment posées",

  faqSubtitle:
    "Réponses simples sur le fonctionnement de Plainspeak Now™.",

  faqQ1:
  "Pourquoi ne pas simplement utiliser ChatGPT ?",

faqA1:
  "Vous le pouvez. Plainspeak Now™ est spécialement conçu pour faciliter la compréhension des documents réels complexes ou difficiles à comprendre, sans que vous ayez à déterminer quoi demander ni comment rédiger une invite.",

faqA1b:
  "Téléversez votre document, collez le texte ou prenez une photo du document. Plainspeak Now™ le traite selon un processus cohérent axé sur la clarté, les informations importantes et les prochaines étapes pratiques.",

faqQ2:
  "Que fait Plainspeak Now™ ?",

faqA2:
  "Plainspeak Now™ réécrit les documents complexes dans un langage quotidien plus clair tout en préservant les informations importantes. Votre résultat peut également identifier les éléments critiques, urgents et importants, fournir une ébauche de réponse professionnelle lorsque cela est approprié, et être traduit ou écouté en audio.",

faqQ3:
  "Que sont les Keys ?",

faqA3:
  "Les Keys sont utilisées pour traiter les documents avec Plainspeak Now™.",

faqA3Bullet1:
  "Les documents jusqu’à 35 pages utilisent 1 Key",

faqA3Bullet2:
  "Les documents de 36 à 70 pages utilisent 2 Keys",

faqA3Bullet3:
  "Les Keys ne sont déduites que lorsque le document a été traité avec succès",

faqA3b:
  "Les Keys n’expirent jamais et aucun abonnement n’est requis.",

faqQ4:
  "Est-ce que je reçois une Key gratuite ?",

faqA4:
  "Oui. Les nouveaux comptes reçoivent 1 Key gratuite pour vous permettre d’essayer Plainspeak Now™. Une Key bonus peut également vous être offerte si vous donnez votre avis.",

faqQ5:
  "Les Keys expirent-elles ?",

faqA5:
  "Non. Vos Keys restent dans votre compte jusqu’à ce que vous les utilisiez.",

faqQ6:
  "Que se passe-t-il si je n’ai plus de Keys ?",

faqA6:
  "Vous pouvez acheter des Keys supplémentaires lorsque vous en avez besoin. Il n’y a aucun abonnement ni prélèvement automatique récurrent.",

faqQ7:
  "Quels types de documents puis-je utiliser ?",

faqA7:
  "Vous pouvez coller du texte, téléverser un fichier pris en charge, ou prendre ou téléverser une photo d’un document. Plainspeak Now™ prend en charge les fichiers PDF, DOCX, TXT, CSV et XLSX, ainsi que les photos de documents et les captures d’écran. Les documents peuvent contenir jusqu’à 70 pages.",

faqQ8:
  "Que devient mon document après son traitement ?",

faqA8:
  "Votre document est utilisé pour créer votre résultat Plainspeak, puis il est supprimé de notre serveur après traitement. Consultez notre Politique de confidentialité pour en savoir plus sur la manière dont les données sont traitées pendant ce processus.",

 faqQ9:
  "Plainspeak Now™ prend-il en charge d’autres langues ?",

faqA9:
  "Oui. Plainspeak Now™ prend en charge l’anglais, l’espagnol, le vietnamien, le tagalog, le français, le chinois simplifié, le coréen, l’arabe, le portugais, le russe, le créole haïtien et l’hindi.",

faqQ10:
  "Plainspeak Now™ peut-il lire mon résultat à voix haute ?",

faqA10:
  "Oui. Vous pouvez générer une lecture audio de votre résultat Plainspeak. L’audio est disponible dans les langues prises en charge.",

faqQ11:
  "Plainspeak Now™ fournit-il des conseils juridiques, médicaux, financiers ou d’autres conseils professionnels ?",

faqA11:
  "Non. Plainspeak Now™ vous aide à comprendre des informations complexes dans un langage plus clair, mais ne fournit pas de conseils juridiques, médicaux, financiers ou d’autres conseils professionnels. Pour les décisions concernant vos droits, votre santé, vos prestations, vos finances ou vos obligations, consultez un professionnel qualifié.",

faqQ12:
  "Plainspeak Now™ modifie-t-il le sens de mon document ?",

faqA12:
  "Plainspeak Now™ est conçu pour préserver le sens et les détails importants de votre document tout en rendant le langage plus facile à comprendre. L’IA peut commettre des erreurs. Utilisez donc le document original comme source faisant autorité et examinez attentivement toute décision importante.",

faqQ13:
  "Puis-je obtenir un remboursement ?",

faqA13:
  "Si vous rencontrez un problème avec un achat ou si Plainspeak Now™ ne fonctionne pas comme prévu, contactez-nous. Les demandes de remboursement sont traitées conformément à nos Conditions d’utilisation.",

faqLastUpdated:
  "Dernière mise à jour : août 2026",

