  faqTitle:
  "常见问题",

faqSubtitle:
  "关于 Plainspeak Now™ 如何使用的简单解答。",

faqQ1:
  "为什么不直接使用 ChatGPT？",

faqA1:
  "当然可以。Plainspeak Now™ 专门用于帮助您更轻松地理解现实生活中复杂或令人困惑的文档，而无需自己考虑该问什么或如何编写提示词。",

faqA1b:
  "您可以上传文档、粘贴文本，或拍摄文档照片。Plainspeak Now™ 会按照一致的流程处理内容，重点关注清晰易懂的解释、重要信息和实用的后续步骤。",

faqQ2:
  "Plainspeak Now™ 能做什么？",

faqA2:
  "Plainspeak Now™ 在保留重要信息的同时，将复杂文档改写成更清晰、更日常的语言。结果还可以识别关键、紧急和重要事项，在适当的情况下提供专业回复草稿，并且可以翻译或通过音频播放。",

faqQ3:
  "什么是 Keys？",

faqA3:
  "Keys 用于在 Plainspeak Now™ 中处理文档。",

faqA3Bullet1:
  "不超过 35 页的文档使用 1 个 Key",

faqA3Bullet2:
  "36 至 70 页的文档使用 2 个 Keys",

faqA3Bullet3:
  "只有在文档成功处理后才会扣除 Keys",

faqA3b:
  "Keys 永不过期，并且无需订阅。",

faqQ4:
  "我可以获得免费的 Key 吗？",

faqA4:
  "可以。新账户会获得 1 个免费 Key，让您可以试用 Plainspeak Now™。您还可能有机会通过提供反馈获得 1 个奖励 Key。",

faqQ5:
  "Keys 会过期吗？",

faqA5:
  "不会。您的 Keys 会一直保留在账户中，直到您使用它们。",

faqQ6:
  "如果我的 Keys 用完了怎么办？",

faqA6:
  "您可以在需要时购买更多 Keys。没有订阅，也不会自动收取周期性费用。",

faqQ7:
  "我可以使用哪些类型的文档？",

faqA7:
  "您可以粘贴文本、上传受支持的文档文件，或者拍摄或上传文档照片。Plainspeak Now™ 支持 PDF、DOCX、TXT、CSV 和 XLSX 文件，以及文档照片和屏幕截图。文档最多可以有 70 页。",

faqQ8:
  "我的文档处理完成后会怎样？",

faqA8:
  "您的文档仅用于生成 Plainspeak 结果，并会在处理完成后从我们的服务器中删除。有关处理过程中如何处理数据的更多信息，请参阅我们的隐私政策。",

faqQ9:
  "Plainspeak Now™ 支持其他语言吗？",

faqA9:
  "支持。Plainspeak Now™ 支持英语、西班牙语、越南语、他加禄语、法语、简体中文、韩语、阿拉伯语、葡萄牙语、俄语、海地克里奥尔语和印地语。",

faqQ10:
  "Plainspeak Now™ 可以朗读我的结果吗？",

faqA10:
  "可以。您可以为 Plainspeak 的结果生成音频播放。音频支持所有受支持的语言。",

faqQ11:
  "Plainspeak Now™ 是否提供法律、医疗、财务或其他专业建议？",

faqA11:
  "不提供。Plainspeak Now™ 可以帮助您用更清晰的语言理解复杂信息，但不提供法律、医疗、财务或其他专业建议。对于影响您的权利、健康、福利、财务或义务的决定，请咨询具备相应资质的专业人士。",

faqQ12:
  "Plainspeak Now™ 会改变我文档的含义吗？",

faqA12:
  "Plainspeak Now™ 旨在保留文档的原意和重要细节，同时让语言更容易理解。AI 可能会出错，因此请将原始文档作为权威来源，并仔细审查任何重要决定。",

faqQ13:
  "我可以退款吗？",

faqA13:
  "如果您在购买时遇到问题，或 Plainspeak Now™ 未按预期工作，请联系我们。退款申请将按照我们的使用条款处理。",

