  faqTitle:
  "자주 묻는 질문",

faqSubtitle:
  "Plainspeak Now™의 작동 방식에 대한 간단한 답변입니다.",

faqQ1:
  "그냥 ChatGPT를 사용하면 안 되나요?",

faqA1:
  "물론 사용할 수 있습니다. Plainspeak Now™는 무엇을 질문해야 하는지 또는 프롬프트를 어떻게 작성해야 하는지 고민할 필요 없이, 복잡하거나 이해하기 어려운 실제 생활의 문서를 더 쉽게 이해할 수 있도록 특별히 설계되었습니다.",

faqA1b:
  "문서를 업로드하거나 텍스트를 붙여넣거나 문서 사진을 찍으세요. Plainspeak Now™는 명확한 설명, 중요한 정보, 실용적인 다음 단계에 초점을 맞춘 일관된 과정으로 문서를 처리합니다.",

faqQ2:
  "Plainspeak Now™는 무엇을 하나요?",

faqA2:
  "Plainspeak Now™는 중요한 정보를 유지하면서 복잡한 문서를 더 명확하고 일상적인 언어로 다시 작성합니다. 결과에서 매우 중요하거나 긴급하거나 중요한 항목을 확인할 수 있으며, 적절한 경우 전문적인 답변 초안을 제공하고 번역하거나 오디오로 들을 수도 있습니다.",

faqQ3:
  "Keys란 무엇인가요?",

faqA3:
  "Keys는 Plainspeak Now™에서 문서를 처리하는 데 사용됩니다.",

faqA3Bullet1:
  "35페이지 이하의 문서는 Key 1개를 사용합니다",

faqA3Bullet2:
  "36~70페이지의 문서는 Keys 2개를 사용합니다",

faqA3Bullet3:
  "Keys는 문서가 성공적으로 처리된 경우에만 차감됩니다",

faqA3b:
  "Keys는 만료되지 않으며 구독이 필요하지 않습니다.",

faqQ4:
  "무료 Key를 받을 수 있나요?",

faqA4:
  "네. 새 계정에는 Plainspeak Now™를 사용해 볼 수 있도록 무료 Key 1개가 제공됩니다. 피드백을 제공하면 보너스 Key를 받을 기회가 제공될 수도 있습니다.",

faqQ5:
  "Keys는 만료되나요?",

faqA5:
  "아니요. Keys는 사용할 때까지 계정에 남아 있습니다.",

faqQ6:
  "Keys를 모두 사용하면 어떻게 되나요?",

faqA6:
  "필요할 때 Keys를 추가로 구매할 수 있습니다. 구독이나 자동 반복 결제는 없습니다.",

faqQ7:
  "어떤 종류의 문서를 사용할 수 있나요?",

faqA7:
  "텍스트를 붙여넣거나 지원되는 문서 파일을 업로드하거나 문서 사진을 찍거나 업로드할 수 있습니다. Plainspeak Now™는 PDF, DOCX, TXT, CSV, XLSX 파일과 문서 사진 및 스크린샷을 지원합니다. 문서는 최대 70페이지까지 처리할 수 있습니다.",

faqQ8:
  "처리 후 제 문서는 어떻게 되나요?",

faqA8:
  "문서는 Plainspeak 결과를 생성하는 데 사용되며 처리 후 당사 서버에서 삭제됩니다. 처리 과정에서 데이터가 어떻게 취급되는지에 대한 자세한 내용은 개인정보 처리방침을 참조하세요.",

faqQ9:
  "Plainspeak Now™는 다른 언어도 지원하나요?",

faqA9:
  "네. Plainspeak Now™는 영어, 스페인어, 베트남어, 타갈로그어, 프랑스어, 중국어 간체, 한국어, 아랍어, 포르투갈어, 러시아어, 아이티 크리올어 및 힌디어를 지원합니다.",

faqQ10:
  "Plainspeak Now™가 결과를 소리 내어 읽어 줄 수 있나요?",

faqA10:
  "네. Plainspeak 결과를 오디오로 생성하여 들을 수 있습니다. 오디오는 지원되는 언어로 제공됩니다.",

faqQ11:
  "Plainspeak Now™는 법률, 의료, 재정 또는 기타 전문적인 조언을 제공하나요?",

faqA11:
  "아니요. Plainspeak Now™는 복잡한 정보를 더 명확한 언어로 이해할 수 있도록 도와주지만 법률, 의료, 재정 또는 기타 전문적인 조언을 제공하지 않습니다. 귀하의 권리, 건강, 혜택, 재정 또는 의무에 영향을 미치는 결정을 내릴 때는 자격을 갖춘 전문가와 상담하세요.",

faqQ12:
  "Plainspeak Now™가 문서의 의미를 변경하나요?",

faqA12:
  "Plainspeak Now™는 문서의 의미와 중요한 세부 사항을 유지하면서 언어를 더 쉽게 이해할 수 있도록 설계되었습니다. AI는 실수할 수 있으므로 원본 문서를 최종적인 기준으로 사용하고 중요한 결정은 신중하게 검토하세요.",

faqQ13:
  "환불받을 수 있나요?",

faqA13:
  "구매와 관련된 문제가 발생했거나 Plainspeak Now™가 예상대로 작동하지 않는 경우 문의해 주세요. 환불 요청은 이용약관에 따라 처리됩니다.",

