whyTitle:
  "لماذا أنشأت Plainspeak Now™",

whyParagraph1:
  "لسنوات، كانت عائلتي تلجأ إليّ عندما تكون الأوراق مربكة أو مرهقة أو يصعب فهمها. وقد رأيت بنفسي مقدار التوتر الذي يمكن أن تسببه وثيقة مهمة عندما لا تكون متأكدًا تمامًا مما تطلبه منك.",

whyParagraph2:
  "أنشأت Plainspeak Now™ لجعل تلك اللحظات أسهل قليلًا. لا ينبغي أن تحتاج إلى شهادة في القانون أو الطب، أو إلى إبقاء قاموس بجانبك، حتى تتمكن من فهم الأوراق التي تؤثر في حياتك.",

