 faqTitle:
  "الأسئلة الشائعة",

faqSubtitle:
  "إجابات بسيطة عن كيفية عمل Plainspeak Now™.",

faqQ1:
  "لماذا لا أستخدم ChatGPT فقط؟",

faqA1:
  "يمكنك ذلك. صُمم Plainspeak Now™ خصيصًا لتسهيل فهم مستندات الحياة اليومية المعقدة أو المربكة، دون أن تحتاج إلى معرفة ما يجب أن تسأل عنه أو كيفية كتابة مطالبة مناسبة.",

faqA1b:
  "حمّل مستندك أو الصق النص أو التقط صورة للمستند. يعالج Plainspeak Now™ المستند من خلال عملية متسقة تركز على الوضوح والمعلومات المهمة والخطوات العملية التالية.",

faqQ2:
  "ماذا يفعل Plainspeak Now™؟",

faqA2:
  "يعيد Plainspeak Now™ كتابة المستندات المعقدة بلغة يومية أكثر وضوحًا مع الحفاظ على المعلومات المهمة. ويمكن لنتيجتك أيضًا تحديد العناصر الحرجة والعاجلة والمهمة، وتقديم مسودة رد مهني عند الاقتضاء، كما يمكن ترجمتها أو تشغيلها كصوت.",

faqQ3:
  "ما هي Keys؟",

faqA3:
  "تُستخدم Keys لمعالجة المستندات باستخدام Plainspeak Now™.",

faqA3Bullet1:
  "تستخدم المستندات التي تصل إلى 35 صفحة Key واحدًا",

faqA3Bullet2:
  "تستخدم المستندات من 36 إلى 70 صفحة 2 Keys",

faqA3Bullet3:
  "يتم خصم Keys فقط عند معالجة المستند بنجاح",

faqA3b:
  "لا تنتهي صلاحية Keys، ولا يلزم الاشتراك.",

faqQ4:
  "هل أحصل على Key مجاني؟",

faqA4:
  "نعم. تحصل الحسابات الجديدة على Key مجاني واحد حتى تتمكن من تجربة Plainspeak Now™. وقد يُعرض عليك أيضًا Key إضافي مقابل تقديم ملاحظاتك.",

faqQ5:
  "هل تنتهي صلاحية Keys؟",

faqA5:
  "لا. تبقى Keys في حسابك حتى تستخدمها.",

faqQ6:
  "ماذا يحدث إذا نفدت Keys لدي؟",

faqA6:
  "يمكنك شراء المزيد من Keys عندما تحتاج إليها. لا يوجد اشتراك ولا رسوم متكررة تلقائية.",

faqQ7:
  "ما أنواع المستندات التي يمكنني استخدامها؟",

faqA7:
  "يمكنك لصق النص أو تحميل ملف مستند مدعوم أو التقاط صورة لمستند أو تحميلها. يدعم Plainspeak Now™ ملفات PDF وDOCX وTXT وCSV وXLSX، بالإضافة إلى صور المستندات ولقطات الشاشة. يمكن أن يصل طول المستند إلى 70 صفحة.",

faqQ8:
  "ماذا يحدث لمستندي بعد معالجته؟",

faqA8:
  "يُستخدم مستندك لإنشاء نتيجة Plainspeak الخاصة بك، ثم يُحذف من خادمنا بعد المعالجة. راجع سياسة الخصوصية الخاصة بنا لمزيد من المعلومات حول كيفية التعامل مع البيانات أثناء المعالجة.",

faqQ9:
  "هل يدعم Plainspeak Now™ لغات أخرى？",

faqA9:
  "نعم. يدعم Plainspeak Now™ الإنجليزية والإسبانية والفيتنامية والتاغالوغية والفرنسية والصينية المبسطة والكورية والعربية والبرتغالية والروسية والكريولية الهايتية والهندية.",

faqQ10:
  "هل يمكن لـ Plainspeak Now™ قراءة النتيجة بصوت عالٍ؟",

faqA10:
  "نعم. يمكنك إنشاء تشغيل صوتي لنتيجة Plainspeak الخاصة بك. يتوفر الصوت باللغات المدعومة.",

faqQ11:
  "هل يقدم Plainspeak Now™ مشورة قانونية أو طبية أو مالية أو غيرها من المشورة المهنية؟",

faqA11:
  "لا. يساعدك Plainspeak Now™ على فهم المعلومات المعقدة بلغة أوضح، لكنه لا يقدم مشورة قانونية أو طبية أو مالية أو غيرها من المشورة المهنية. بالنسبة للقرارات التي تؤثر في حقوقك أو صحتك أو مزاياك أو أموالك أو التزاماتك، استشر متخصصًا مؤهلًا.",

faqQ12:
  "هل يغيّر Plainspeak Now™ معنى مستندي؟",

faqA12:
  "تم تصميم Plainspeak Now™ للحفاظ على معنى مستندك وتفاصيله المهمة مع جعل اللغة أسهل في الفهم. قد يرتكب الذكاء الاصطناعي أخطاء، لذلك استخدم المستند الأصلي باعتباره المصدر المعتمد وراجع القرارات المهمة بعناية.",

faqQ13:
  "هل يمكنني استرداد أموالي؟",

faqA13:
  "إذا واجهت مشكلة في عملية شراء أو لم يعمل Plainspeak Now™ كما هو متوقع، فتواصل معنا. تتم معالجة طلبات استرداد الأموال وفقًا لشروط الاستخدام الخاصة بنا.",

