whyTitle:
  "Por que criei o Plainspeak Now™",

whyParagraph1:
  "Durante anos, minha família recorria a mim quando a papelada era confusa, cansativa ou simplesmente difícil de entender. Vi de perto o estresse que um documento importante pode causar quando você não tem certeza do que ele está pedindo que você faça.",

whyParagraph2:
  "Criei o Plainspeak Now™ para tornar esses momentos um pouco mais fáceis. Você não deveria precisar de um diploma em Direito, um diploma em Medicina ou um dicionário ao seu lado para entender os documentos que afetam sua vida.",

