  faqTitle:
  "Perguntas frequentes",

faqSubtitle:
  "Respostas simples sobre como o Plainspeak Now™ funciona.",

faqQ1:
  "Por que não usar apenas o ChatGPT?",

faqA1:
  "Você pode. O Plainspeak Now™ foi criado especificamente para facilitar a compreensão de documentos reais que podem ser complicados ou confusos, sem que você precise descobrir o que perguntar ou como escrever um prompt.",

faqA1b:
  "Envie seu documento, cole o texto ou tire uma foto do documento. O Plainspeak Now™ conduz o conteúdo por um processo consistente, com foco em clareza, informações importantes e próximos passos práticos.",

faqQ2:
  "O que o Plainspeak Now™ faz?",

faqA2:
  "O Plainspeak Now™ reescreve documentos complicados em uma linguagem mais clara e cotidiana, preservando as informações importantes. Seu resultado também pode identificar itens críticos, urgentes e importantes, fornecer um rascunho de resposta profissional quando apropriado e ser traduzido ou reproduzido em áudio.",

faqQ3:
  "O que são Keys?",

faqA3:
  "As Keys são usadas para processar documentos com o Plainspeak Now™.",

faqA3Bullet1:
  "Documentos de até 35 páginas usam 1 Key",

faqA3Bullet2:
  "Documentos de 36 a 70 páginas usam 2 Keys",

faqA3Bullet3:
  "As Keys só são descontadas quando o documento é processado com sucesso",

faqA3b:
  "As Keys nunca expiram e não é necessário ter uma assinatura.",

faqQ4:
  "Eu recebo uma Key grátis?",

faqA4:
  "Sim. Novas contas recebem 1 Key grátis para que você possa experimentar o Plainspeak Now™. Você também poderá receber a oferta de uma Key bônus por fornecer feedback.",

faqQ5:
  "As Keys expiram?",

faqA5:
  "Não. Suas Keys permanecem na sua conta até que você as use.",

faqQ6:
  "O que acontece se minhas Keys acabarem?",

faqA6:
  "Você pode comprar mais Keys quando precisar. Não há assinatura nem cobrança recorrente automática.",

faqQ7:
  "Que tipos de documentos posso usar?",

faqA7:
  "Você pode colar texto, enviar um arquivo de documento compatível ou tirar ou enviar uma foto de um documento. O Plainspeak Now™ aceita arquivos PDF, DOCX, TXT, CSV e XLSX, além de fotos de documentos e capturas de tela. Os documentos podem ter até 70 páginas.",

faqQ8:
  "O que acontece com meu documento depois que ele é processado?",

faqA8:
  "Seu documento é usado para criar seu resultado do Plainspeak e é excluído do nosso servidor após o processamento. Consulte nossa Política de Privacidade para obter mais informações sobre como os dados são tratados durante o processamento.",

faqQ9:
  "O Plainspeak Now™ oferece suporte a outros idiomas?",

faqA9:
  "Sim. O Plainspeak Now™ oferece suporte a inglês, espanhol, vietnamita, tagalo, francês, chinês simplificado, coreano, árabe, português, russo, crioulo haitiano e hindi.",

faqQ10:
  "O Plainspeak Now™ pode ler meu resultado em voz alta?",

faqA10:
  "Sim. Você pode gerar uma reprodução em áudio do seu resultado do Plainspeak. O áudio está disponível nos idiomas compatíveis.",

faqQ11:
  "O Plainspeak Now™ fornece aconselhamento jurídico, médico, financeiro ou outro aconselhamento profissional?",

faqA11:
  "Não. O Plainspeak Now™ ajuda você a entender informações complexas em uma linguagem mais clara, mas não fornece aconselhamento jurídico, médico, financeiro ou outro aconselhamento profissional. Para decisões que afetem seus direitos, sua saúde, seus benefícios, suas finanças ou suas obrigações, consulte um profissional qualificado.",

faqQ12:
  "O Plainspeak Now™ altera o significado do meu documento?",

faqA12:
  "O Plainspeak Now™ foi desenvolvido para preservar o significado e os detalhes importantes do seu documento, tornando a linguagem mais fácil de entender. A IA pode cometer erros, portanto use o documento original como fonte oficial e analise cuidadosamente as decisões importantes.",

faqQ13:
  "Posso receber um reembolso?",

faqA13:
  "Se você tiver algum problema com uma compra ou se o Plainspeak Now™ não funcionar como esperado, entre em contato conosco. As solicitações de reembolso são tratadas de acordo com nossos Termos de Uso.",

faqLastUpdated:
  "Última atualização: agosto de 2026",
