   faqTitle:
  "Часто задаваемые вопросы",

faqSubtitle:
  "Простые ответы о том, как работает Plainspeak Now™.",

faqQ1:
  "Почему бы просто не использовать ChatGPT?",

faqA1:
  "Можно. Plainspeak Now™ создан специально для того, чтобы сложные и запутанные документы из реальной жизни было легче понять, без необходимости самостоятельно решать, что спросить или как составить запрос.",

faqA1b:
  "Загрузите документ, вставьте текст или сфотографируйте документ. Plainspeak Now™ проведет его через последовательный процесс, ориентированный на ясность, важную информацию и практические следующие шаги.",

faqQ2:
  "Что делает Plainspeak Now™?",

faqA2:
  "Plainspeak Now™ переписывает сложные документы более ясным и повседневным языком, сохраняя важную информацию. Результат также может выделять критические, срочные и важные сведения, предоставлять черновик профессионального ответа, когда это уместно, а также переводиться или воспроизводиться в виде аудио.",

faqQ3:
  "Что такое Keys?",

faqA3:
  "Keys используются для обработки документов в Plainspeak Now™.",

faqA3Bullet1:
  "Для документов объемом до 35 страниц используется 1 Key",

faqA3Bullet2:
  "Для документов объемом от 36 до 70 страниц используются 2 Keys",

faqA3Bullet3:
  "Keys списываются только после успешной обработки документа",

faqA3b:
  "Keys никогда не истекают, и подписка не требуется.",

faqQ4:
  "Получу ли я бесплатный Key?",

faqA4:
  "Да. Новые аккаунты получают 1 бесплатный Key, чтобы вы могли попробовать Plainspeak Now™. Вам также может быть предложен бонусный Key за предоставление отзыва.",

faqQ5:
  "Истекает ли срок действия Keys?",

faqA5:
  "Нет. Ваши Keys остаются в аккаунте, пока вы их не используете.",

faqQ6:
  "Что произойдет, если у меня закончатся Keys?",

faqA6:
  "Вы можете приобрести дополнительные Keys, когда они вам понадобятся. Подписки и автоматических регулярных списаний нет.",

faqQ7:
  "Какие документы можно использовать?",

faqA7:
  "Вы можете вставить текст, загрузить поддерживаемый файл документа, а также сделать или загрузить фотографию документа. Plainspeak Now™ поддерживает файлы PDF, DOCX, TXT, CSV и XLSX, а также фотографии документов и снимки экрана. Документы могут содержать до 70 страниц.",

faqQ8:
  "Что происходит с моим документом после обработки?",

faqA8:
  "Ваш документ используется для создания результата Plainspeak и удаляется с нашего сервера после обработки. Дополнительную информацию о том, как данные обрабатываются во время этого процесса, см. в нашей Политике конфиденциальности.",

faqQ9:
  "Поддерживает ли Plainspeak Now™ другие языки?",

faqA9:
  "Да. Plainspeak Now™ поддерживает английский, испанский, вьетнамский, тагальский, французский, упрощённый китайский, корейский, арабский, португальский, русский, гаитянский креольский и хинди.",

faqQ10:
  "Может ли Plainspeak Now™ прочитать мой результат вслух?",

faqA10:
  "Да. Вы можете создать аудиоверсию своего результата Plainspeak. Аудио доступно на поддерживаемых языках.",

faqQ11:
  "Предоставляет ли Plainspeak Now™ юридические, медицинские, финансовые или другие профессиональные консультации?",

faqA11:
  "Нет. Plainspeak Now™ помогает понять сложную информацию более простым и понятным языком, но не предоставляет юридических, медицинских, финансовых или других профессиональных консультаций. При принятии решений, затрагивающих ваши права, здоровье, льготы, финансы или обязательства, проконсультируйтесь с квалифицированным специалистом.",

faqQ12:
  "Изменяет ли Plainspeak Now™ смысл моего документа?",

faqA12:
  "Plainspeak Now™ разработан так, чтобы сохранять смысл и важные детали вашего документа, делая язык более понятным. ИИ может допускать ошибки, поэтому используйте оригинал документа как основной источник и внимательно проверяйте информацию перед принятием важных решений.",

faqQ13:
  "Могу ли я получить возврат средств?",

faqA13:
  "Если у вас возникла проблема с покупкой или Plainspeak Now™ работает не так, как ожидалось, свяжитесь с нами. Запросы на возврат средств рассматриваются в соответствии с нашими Условиями использования.",

