 faqTitle:
  "Kesyon yo poze souvan",

faqSubtitle:
  "Repons senp sou fason Plainspeak Now™ fonksyone.",

faqQ1:
  "Poukisa mwen pa jis itilize ChatGPT?",

faqA1:
  "Ou kapab. Plainspeak Now™ fèt espesyalman pou rann dokiman lavi chak jou ki konplike oswa konfizyon pi fasil pou konprann, san ou pa bezwen konnen kisa pou mande oswa kijan pou ekri yon bon prompt.",

faqA1b:
  "Telechaje dokiman ou, kole tèks la, oswa pran yon foto dokiman an. Plainspeak Now™ mennen li atravè yon pwosesis ki konsistan, ki konsantre sou klète, enfòmasyon enpòtan ak pwochen etap pratik yo.",

faqQ2:
  "Kisa Plainspeak Now™ fè?",

faqA2:
  "Plainspeak Now™ reekri dokiman konplike nan yon langaj ki pi klè epi ki pi fasil pou konprann, pandan li konsève enfòmasyon enpòtan yo. Rezilta ou a ka idantifye tou bagay ki kritik, ijan ak enpòtan, bay yon bouyon repons pwofesyonèl lè sa apwopriye, epi li ka tradui oswa jwe kòm odyo.",

faqQ3:
  "Kisa Keys ye?",

faqA3:
  "Keys se sa Plainspeak Now™ itilize pou trete dokiman yo.",

faqA3Bullet1:
  "Dokiman ki gen jiska 35 paj itilize 1 Key",

faqA3Bullet2:
  "Dokiman ki gen 36 rive 70 paj itilize 2 Keys",

faqA3Bullet3:
  "Keys retire sèlman lè dokiman an trete avèk siksè",

faqA3b:
  "Keys pa janm ekspire, epi ou pa bezwen okenn abònman.",

faqQ4:
  "Èske mwen jwenn yon Key gratis?",

faqA4:
  "Wi. Nouvo kont yo resevwa 1 Key gratis pou ou ka eseye Plainspeak Now™. Yo ka ofri w tou yon Key bonis si ou bay fidbak.",

faqQ5:
  "Èske Keys ekspire?",

faqA5:
  "Non. Keys ou yo rete nan kont ou jiskaske ou itilize yo.",

faqQ6:
  "Kisa k ap pase si Keys mwen yo fini?",

faqA6:
  "Ou ka achte plis Keys lè ou bezwen yo. Pa gen abònman ni frè renouvlab otomatik.",

faqQ7:
  "Ki kalite dokiman mwen ka itilize?",

faqA7:
  "Ou ka kole tèks, telechaje yon fichye dokiman ki sipòte, oswa pran oswa telechaje yon foto yon dokiman. Plainspeak Now™ sipòte fichye PDF, DOCX, TXT, CSV ak XLSX, ansanm ak foto dokiman ak kaptire ekran. Dokiman yo ka gen jiska 70 paj.",

faqQ8:
  "Kisa k ap pase ak dokiman mwen an apre yo fin trete li?",

faqA8:
  "Yo itilize dokiman ou sèlman pou kreye rezilta Plainspeak ou a, epi yo efase li nan sèvè nou an apre pwosesis la fini. Gade Règleman sou Konfidansyalite nou an pou plis enfòmasyon sou fason done yo trete pandan pwosesis la.",

faqQ9:
  "Èske Plainspeak Now™ sipòte lòt lang?",

faqA9:
  "Wi. Plainspeak Now™ sipòte anglè, panyòl, vyetnamyen, tagalog, franse, chinwa senplifye, koreyen, arab, pòtigè, ris, kreyòl ayisyen ak hindi.",

faqQ10:
  "Èske Plainspeak Now™ ka li rezilta mwen an byen fò?",

faqA10:
  "Wi. Ou ka kreye yon vèsyon odyo pou rezilta Plainspeak ou a. Odyo disponib nan lang ki sipòte yo.",

faqQ11:
  "Èske Plainspeak Now™ bay konsèy legal, medikal, finansye oswa lòt konsèy pwofesyonèl?",

faqA11:
  "Non. Plainspeak Now™ ede w konprann enfòmasyon konplike nan yon langaj ki pi klè, men li pa bay konsèy legal, medikal, finansye oswa lòt konsèy pwofesyonèl. Pou desizyon ki afekte dwa w, sante w, benefis ou, finans ou oswa obligasyon ou, konsilte yon pwofesyonèl ki kalifye.",

faqQ12:
  "Èske Plainspeak Now™ chanje sans dokiman mwen an?",

faqA12:
  "Plainspeak Now™ fèt pou konsève sans ak detay enpòtan nan dokiman ou pandan li fè langaj la pi fasil pou konprann. AI ka fè erè, kidonk sèvi ak dokiman orijinal la kòm sous prensipal la epi verifye ak anpil atansyon anvan ou pran desizyon enpòtan.",

faqQ13:
  "Èske mwen ka jwenn yon ranbousman?",

faqA13:
  "Si ou gen yon pwoblèm ak yon acha oswa Plainspeak Now™ pa mache jan ou te espere a, kontakte nou. Nou trete demann ranbousman yo dapre Kondisyon Itilizasyon nou yo.",

