  "मैंने Plainspeak Now™ क्यों बनाया",

whyParagraph1:
  "कई वर्षों से, जब दस्तावेज़ उलझे हुए, भारी या समझने में मुश्किल होते थे, मेरा परिवार मेरे पास आता था। मैंने खुद देखा है कि जब किसी महत्वपूर्ण दस्तावेज़ में यह स्पष्ट न हो कि आपसे क्या करने की अपेक्षा की जा रही है, तो वह कितना तनाव पैदा कर सकता है।",

whyParagraph2:
  "मैंने Plainspeak Now™ ऐसे पलों को थोड़ा आसान बनाने के लिए बनाया। आपकी ज़िंदगी को प्रभावित करने वाले दस्तावेज़ों को समझने के लिए आपके पास कानून या चिकित्सा की डिग्री, या बगल में कोई शब्दकोश होना ज़रूरी नहीं होना चाहिए।",

whyClosing:
  "आप समझने के हकदार हैं, इससे पहले कि आप प्रतिबद्ध हों।",
