privacyPlainTitle:
  "Plainspeak Now™ संस्करण (आसानी से समझने योग्य)",

privacyPlainP1:
  "हम Plainspeak Now™ प्रदान करने और संचालित करने के लिए आवश्यक जानकारी एकत्र करते हैं, जैसे आपके खाते की जानकारी, Keys का बैलेंस, उपयोग संबंधी जानकारी और वह जानकारी जो आप स्वेच्छा से हमें प्रदान करते हैं।",

privacyPlainP2:
  "जब आप टेक्स्ट पेस्ट करते हैं, कोई दस्तावेज़ अपलोड करते हैं या कोई फ़ोटो भेजते हैं, तो उस सामग्री का उपयोग आपका Plainspeak Now™ परिणाम बनाने के लिए किया जाता है। प्रोसेसिंग के बाद आपके दस्तावेज़ की सामग्री हमारे सर्वर से हटा दी जाती है।",

privacyPlainP3:
  "कुछ सुविधाओं के लिए विश्वसनीय सेवा प्रदाताओं को हमारी ओर से जानकारी प्रोसेस करने की आवश्यकता होती है। उदाहरण के लिए, बाहरी सेवाएँ खातों को प्रमाणित करने, चित्रों से टेक्स्ट निकालने, स्पष्ट भाषा में परिणाम और ऑडियो बनाने, भुगतान प्रोसेस करने या ईमेल भेजने में हमारी सहायता कर सकती हैं।",

privacyPlainP4:
  "हम सेवा चलाने के लिए आवश्यक खाते और संचालन संबंधी जानकारी रखते हैं, जैसे आपका Keys बैलेंस और फ़ीडबैक की स्थिति। यदि आप स्वेच्छा से फ़ीडबैक देते हैं या हमसे संपर्क करते हैं, तो हम उस जानकारी को भी रख सकते हैं।",

privacyPlainP5:
  "हम आपकी व्यक्तिगत जानकारी नहीं बेचते और आपके दस्तावेज़ की सामग्री का उपयोग आपको विज्ञापन दिखाने के लिए नहीं करते। यदि आपके पास गोपनीयता से संबंधित कोई प्रश्न या अनुरोध है, तो आप हमसे संपर्क कर सकते हैं।",

